import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import AdminSidebar from '../../components/AdminSidebar';
import toast from 'react-hot-toast';
import './AdminPetsPage.css';

const AdminPetsPage = () => {
  const { user, api } = useAuth();
  const navigate = useNavigate();
  const [pets, setPets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [showFilterModal, setShowFilterModal] = useState(false);
  const [editingPet, setEditingPet] = useState(null);
  const [filters, setFilters] = useState({
    type: [],
    sex: [],
    age: [],
    status: [],
    rescue: []
  });

  // Form state
  const [formData, setFormData] = useState({
    name: '',
    type: 'Dog',
    sex: 'Male',
    age: 'Young',
    breed: '',
    status: 'Available',
    rescueStatus: 'Rescued',
    description: '',
    vaccinationHistory: '',
    medicalNotes: '',
    adoptionFee: 0,
    imageData: null
  });

  useEffect(() => {
    if (!user || user.role !== 'admin') {
      navigate('/admin/login');
      return;
    }
    fetchPets();
  }, [user, navigate]);

  const fetchPets = async () => {
    try {
      const response = await api.get('/pets');
      setPets(response.data);
    } catch (error) {
      console.error('Error fetching pets:', error);
      toast.error('Failed to load pets');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const petData = new FormData();
    petData.append('name', formData.name);
    petData.append('type', formData.type);
    petData.append('sex', formData.sex);
    petData.append('age', formData.age);
    petData.append('breed', formData.breed);
    petData.append('status', formData.status);
    petData.append('rescueStatus', formData.rescueStatus);
    petData.append('description', formData.description);
    petData.append('vaccinationHistory', formData.vaccinationHistory);
    petData.append('medicalNotes', formData.medicalNotes);
    petData.append('adoptionFee', formData.adoptionFee);

    if (formData.imageData) {
      petData.append('image', formData.imageData);
    }

    try {
      if (editingPet) {
        await api.put(`/pets/${editingPet._id}`, petData);
        toast.success('Pet updated successfully!');
      } else {
        await api.post('/pets', petData);
        toast.success('Pet added successfully!');
      }
      fetchPets();
      closeModal();
    } catch (error) {
      console.error('Error saving pet:', error);
      toast.error(error.response?.data?.message || 'Failed to save pet');
    }
  };

  const handleDelete = async (petId) => {
    if (window.confirm('Are you sure you want to delete this pet?')) {
      try {
        await api.delete(`/pets/${petId}`);
        toast.success('Pet deleted successfully!');
        fetchPets();
      } catch (error) {
        console.error('Error deleting pet:', error);
        toast.error('Failed to delete pet');
      }
    }
  };

  const openModal = (pet = null) => {
    if (pet) {
      setEditingPet(pet);
      setFormData({
        name: pet.name,
        type: pet.type,
        sex: pet.sex,
        age: pet.age,
        breed: pet.breed || '',
        status: pet.status,
        rescueStatus: pet.rescueStatus,
        description: pet.description,
        vaccinationHistory: pet.vaccinationHistory || '',
        medicalNotes: pet.medicalNotes || '',
        adoptionFee: pet.adoptionFee || 0,
        imageData: null
      });
    } else {
      setEditingPet(null);
      setFormData({
        name: '',
        type: 'Dog',
        sex: 'Male',
        age: 'Young',
        breed: '',
        status: 'Available',
        rescueStatus: 'Rescued',
        description: '',
        vaccinationHistory: '',
        medicalNotes: '',
        adoptionFee: 0,
        imageData: null
      });
    }
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setEditingPet(null);
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFormData({ ...formData, imageData: file });
    }
  };

  const filteredPets = pets.filter(pet => {
    if (searchTerm && !pet.name.toLowerCase().includes(searchTerm.toLowerCase())) {
      return false;
    }
    if (filters.type.length && !filters.type.includes(pet.type)) return false;
    if (filters.sex.length && !filters.sex.includes(pet.sex)) return false;
    if (filters.age.length && !filters.age.includes(pet.age)) return false;
    if (filters.status.length && !filters.status.includes(pet.status)) return false;
    if (filters.rescue.length && !filters.rescue.includes(pet.rescueStatus)) return false;
    return true;
  });

  if (loading) {
    return (
      <div className="admin-wrapper">
        <AdminSidebar />
        <div className="admin-loading">Loading...</div>
      </div>
    );
  }

  return (
    <div className="admin-wrapper">
      <AdminSidebar />
      <main className="admin-content">
        <div className="page-header">
          <h1><i className="fas fa-paw"></i> MANAGE PETS</h1>
          <button className="add-pet-btn" onClick={() => openModal()}>
            <i className="fas fa-plus"></i> Add New Pet
          </button>
        </div>

        <div className="filter-bar">
          <div className="search-bar">
            <i className="fas fa-search"></i>
            <input
              type="text"
              placeholder="Search by name..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button className="filter-btn" onClick={() => setShowFilterModal(true)}>
            <i className="fas fa-sliders-h"></i> Filter
          </button>
        </div>

        <div className="pets-table-container">
          <table className="pets-table">
            <thead>
              <tr>
                <th>Image</th>
                <th>Name</th>
                <th>Type</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredPets.map(pet => (
                <tr key={pet._id}>
                  <td>
                    <div className="pet-image">
                      {pet.imageData ? (
                        <img src={pet.imageData} alt={pet.name} />
                      ) : (
                        <i className={`fas fa-${pet.type === 'Dog' ? 'dog' : 'cat'} fa-2x`}></i>
                      )}
                    </div>
                  </td>
                  <td><strong>{pet.name}</strong></td>
                  <td>{pet.type}</td>
                  <td>
                    <span className={`status-badge ${pet.status === 'Available' ? 'status-available' : 'status-adopted'}`}>
                      {pet.status}
                    </span>
                  </td>
                  <td>
                    <div className="action-buttons">
                      <button className="action-btn view" onClick={() => openModal(pet)}>
                        <i className="fas fa-edit"></i> Edit
                      </button>
                      <button className="action-btn delete" onClick={() => handleDelete(pet._id)}>
                        <i className="fas fa-trash"></i> Delete
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {filteredPets.length === 0 && (
            <div className="no-data">No pets found</div>
          )}
        </div>
      </main>

      {/* Add/Edit Pet Modal */}
      {showModal && (
        <div className="modal-overlay active" onClick={closeModal}>
          <div className="modal-container" onClick={(e) => e.stopPropagation()}>
            <i className="fas fa-times modal-close" onClick={closeModal}></i>
            <h2>{editingPet ? 'EDIT PET' : 'ADD NEW PET'}</h2>
            <form onSubmit={handleSubmit}>
              <div className="form-group">
                <label>Pet Name *</label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  required
                />
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>Type</label>
                  <select value={formData.type} onChange={(e) => setFormData({ ...formData, type: e.target.value })}>
                    <option value="Dog">Dog</option>
                    <option value="Cat">Cat</option>
                  </select>
                </div>
                <div className="form-group">
                  <label>Sex</label>
                  <select value={formData.sex} onChange={(e) => setFormData({ ...formData, sex: e.target.value })}>
                    <option value="Male">Male</option>
                    <option value="Female">Female</option>
                  </select>
                </div>
                <div className="form-group">
                  <label>Age</label>
                  <select value={formData.age} onChange={(e) => setFormData({ ...formData, age: e.target.value })}>
                    <option value="Baby">Baby</option>
                    <option value="Young">Young</option>
                    <option value="Adult">Adult</option>
                    <option value="Senior">Senior</option>
                  </select>
                </div>
              </div>
              <div className="form-group">
                <label>Breed</label>
                <input
                  type="text"
                  value={formData.breed}
                  onChange={(e) => setFormData({ ...formData, breed: e.target.value })}
                  placeholder="e.g., Aspin, Mixed, Persian"
                />
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>Status</label>
                  <select value={formData.status} onChange={(e) => setFormData({ ...formData, status: e.target.value })}>
                    <option value="Available">Available</option>
                    <option value="Adopted">Adopted</option>
                    <option value="Pending">Pending</option>
                  </select>
                </div>
                <div className="form-group">
                  <label>Rescue Status</label>
                  <select value={formData.rescueStatus} onChange={(e) => setFormData({ ...formData, rescueStatus: e.target.value })}>
                    <option value="Rescued">Rescued</option>
                    <option value="Stray">Stray</option>
                    <option value="Surrendered">Surrendered</option>
                  </select>
                </div>
                <div className="form-group">
                  <label>Adoption Fee (PHP)</label>
                  <input
                    type="number"
                    value={formData.adoptionFee}
                    onChange={(e) => setFormData({ ...formData, adoptionFee: parseInt(e.target.value) })}
                  />
                </div>
              </div>
              <div className="form-group">
                <label>Description</label>
                <textarea
                  rows="3"
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  placeholder="Describe the pet's personality, behavior, etc."
                />
              </div>
              <div className="form-group">
                <label>Vaccination History</label>
                <textarea
                  rows="2"
                  value={formData.vaccinationHistory}
                  onChange={(e) => setFormData({ ...formData, vaccinationHistory: e.target.value })}
                  placeholder="List vaccinations given"
                />
              </div>
              <div className="form-group">
                <label>Medical Notes</label>
                <textarea
                  rows="2"
                  value={formData.medicalNotes}
                  onChange={(e) => setFormData({ ...formData, medicalNotes: e.target.value })}
                  placeholder="Any medical conditions or notes"
                />
              </div>
              <div className="form-group">
                <label>Upload Image</label>
                <div className="file-input-wrapper" onClick={() => document.getElementById('petImage').click()}>
                  <i className="fas fa-cloud-upload-alt"></i>
                  <span>{formData.imageData ? formData.imageData.name : 'Click to upload image'}</span>
                </div>
                <input type="file" id="petImage" accept="image/*" onChange={handleImageChange} style={{ display: 'none' }} />
              </div>
              <button type="submit" className="save-btn">
                <i className="fas fa-save"></i> {editingPet ? 'Update Pet' : 'Save Pet'}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Filter Modal */}
      {showFilterModal && (
        <div className="modal-overlay active" onClick={() => setShowFilterModal(false)}>
          <div className="modal-container filter-modal" onClick={(e) => e.stopPropagation()}>
            <i className="fas fa-times modal-close" onClick={() => setShowFilterModal(false)}></i>
            <h2>Filter Pets</h2>
            <div className="filter-group">
              <label>Type</label>
              <div className="filter-options">
                <label><input type="checkbox" value="Dog" onChange={(e) => {
                  if (e.target.checked) setFilters({ ...filters, type: [...filters.type, 'Dog'] });
                  else setFilters({ ...filters, type: filters.type.filter(t => t !== 'Dog') });
                }} /> Dog</label>
                <label><input type="checkbox" value="Cat" onChange={(e) => {
                  if (e.target.checked) setFilters({ ...filters, type: [...filters.type, 'Cat'] });
                  else setFilters({ ...filters, type: filters.type.filter(t => t !== 'Cat') });
                }} /> Cat</label>
              </div>
            </div>
            <div className="filter-group">
              <label>Sex</label>
              <div className="filter-options">
                <label><input type="checkbox" value="Male" onChange={(e) => {
                  if (e.target.checked) setFilters({ ...filters, sex: [...filters.sex, 'Male'] });
                  else setFilters({ ...filters, sex: filters.sex.filter(s => s !== 'Male') });
                }} /> Male</label>
                <label><input type="checkbox" value="Female" onChange={(e) => {
                  if (e.target.checked) setFilters({ ...filters, sex: [...filters.sex, 'Female'] });
                  else setFilters({ ...filters, sex: filters.sex.filter(s => s !== 'Female') });
                }} /> Female</label>
              </div>
            </div>
            <div className="filter-group">
              <label>Age</label>
              <div className="filter-options">
                <label><input type="checkbox" value="Baby" onChange={(e) => {
                  if (e.target.checked) setFilters({ ...filters, age: [...filters.age, 'Baby'] });
                  else setFilters({ ...filters, age: filters.age.filter(a => a !== 'Baby') });
                }} /> Baby</label>
                <label><input type="checkbox" value="Young" onChange={(e) => {
                  if (e.target.checked) setFilters({ ...filters, age: [...filters.age, 'Young'] });
                  else setFilters({ ...filters, age: filters.age.filter(a => a !== 'Young') });
                }} /> Young</label>
                <label><input type="checkbox" value="Adult" onChange={(e) => {
                  if (e.target.checked) setFilters({ ...filters, age: [...filters.age, 'Adult'] });
                  else setFilters({ ...filters, age: filters.age.filter(a => a !== 'Adult') });
                }} /> Adult</label>
              </div>
            </div>
            <div className="filter-group">
              <label>Status</label>
              <div className="filter-options">
                <label><input type="checkbox" value="Available" onChange={(e) => {
                  if (e.target.checked) setFilters({ ...filters, status: [...filters.status, 'Available'] });
                  else setFilters({ ...filters, status: filters.status.filter(s => s !== 'Available') });
                }} /> Available</label>
                <label><input type="checkbox" value="Adopted" onChange={(e) => {
                  if (e.target.checked) setFilters({ ...filters, status: [...filters.status, 'Adopted'] });
                  else setFilters({ ...filters, status: filters.status.filter(s => s !== 'Adopted') });
                }} /> Adopted</label>
              </div>
            </div>
            <button className="apply-filter-btn" onClick={() => setShowFilterModal(false)}>
              Apply Filter
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminPetsPage;
